// L2 只读投影（工作台）+ 工作台视图（同一业务域合并）
// 依赖：workbench -> tasks 公共只读接口 + L0 日期工具；视图额外注入 navigate / today / chrome。
import { isISODate, toLocalISODate } from '../infra/storage.js';

// 「未完成」= 除「已发布」外的三个状态（与架构 2.3 节一致）。
export const UNFINISHED_STATUSES = ['todo', 'writing', 'toPublish'];
export const WORKBENCH_STATUS_LABELS = [
  ['todo', '待写作'],
  ['writing', '写作中'],
  ['toPublish', '待发布'],
  ['published', '已发布'],
];

// today 允许字符串日期、Date 或返回日期的函数（装配根注入 toLocalISODate）。
function normalizeToday(today) {
  if (typeof today === 'function') return normalizeToday(today());
  if (typeof today === 'string' && today !== '') return today;
  if (today instanceof Date) return toLocalISODate(today);
  return toLocalISODate();
}

function readDueDate(record) {
  return record && typeof record.dueDate === 'string' ? record.dueDate : '';
}

// 逾期 = 未完成且截止日期早于本地当天；无截止日期或日期非法都不计入。
function isOverdue(record, today) {
  const dueDate = readDueDate(record);
  return dueDate !== '' && isISODate(dueDate) && dueDate < today;
}

export function createWorkbenchModule({ tasks } = {}) {
  if (!tasks) throw new Error('createWorkbenchModule requires { tasks }');
  return {
    // 返回 { unfinished, overdue, counts, total }；只读，不写任何集合。
    getSummary(today) {
      const todayDate = normalizeToday(today);
      const listed = tasks.list();
      const records = Array.isArray(listed) ? listed : [];
      const counts = { todo: 0, writing: 0, toPublish: 0, published: 0 };
      for (const record of records) {
        if (record && Object.prototype.hasOwnProperty.call(counts, record.status)) {
          counts[record.status] += 1;
        }
      }
      const unfinished = records.filter(
        (record) => record && UNFINISHED_STATUSES.includes(record.status),
      );
      const overdue = unfinished.filter((record) => isOverdue(record, todayDate));
      return { unfinished, overdue, counts, total: records.length };
    },
  };
}

function fillContainer(container, children) {
  if (typeof container.replaceChildren === 'function') {
    container.replaceChildren(...children);
    return;
  }
  while (container.firstChild) container.removeChild(container.firstChild);
  for (const child of children) container.appendChild(child);
}

export function createWorkbenchView({ workbench, navigate, today, chrome } = {}) {
  if (!workbench || typeof navigate !== 'function') {
    throw new Error('createWorkbenchView requires { workbench, navigate }');
  }
  // 视图只经 navigate 端口切换路由，不自行改 location / history；chrome 由外壳统一处理提示。
  void chrome;

  let host = null;
  let doc = null;
  let nodes = null;

  function make(tag, testid, text) {
    const element = doc.createElement(tag);
    if (testid) element.setAttribute('data-testid', testid);
    if (text !== undefined) element.textContent = text;
    return element;
  }

  function build() {
    const root = make('section', 'workbench-view');
    root.setAttribute('class', 'workbench-view');

    const summary = make('div', 'workbench-summary');
    summary.setAttribute('class', 'workbench-summary');

    const unfinishedLine = make('p', 'workbench-unfinished-line');
    unfinishedLine.setAttribute('class', 'workbench-summary-line');
    unfinishedLine.appendChild(make('span', null, '未完成任务数：'));
    const unfinishedCount = make('span', 'workbench-unfinished-count', '0');
    unfinishedLine.appendChild(unfinishedCount);

    const overdueLine = make('p', 'workbench-overdue-line');
    overdueLine.setAttribute('class', 'workbench-summary-line');
    overdueLine.appendChild(make('span', null, '逾期任务数：'));
    const overdueCount = make('span', 'workbench-overdue-count', '0');
    overdueLine.appendChild(overdueCount);

    const statusCounts = make('ul', 'workbench-status-counts');
    statusCounts.setAttribute('class', 'workbench-status-counts');
    const countNodes = {};
    for (const [status, label] of WORKBENCH_STATUS_LABELS) {
      const item = make('li', 'workbench-status-count-item');
      item.setAttribute('class', 'workbench-status-count-item');
      item.setAttribute('data-status', status);
      item.appendChild(make('span', null, label + '：'));
      const value = make('span', 'workbench-status-count-' + status, '0');
      item.appendChild(value);
      statusCounts.appendChild(item);
      countNodes[status] = value;
    }

    summary.appendChild(unfinishedLine);
    summary.appendChild(overdueLine);
    summary.appendChild(statusCounts);

    const unfinishedSection = make('section', 'workbench-unfinished-section');
    const unfinishedHeading = make('h3', null, '未完成任务');
    const unfinishedList = make('ul', 'workbench-unfinished-list');
    const unfinishedHint = make('p', null, '暂无未完成任务');
    unfinishedHint.setAttribute('class', 'workbench-empty-hint');
    unfinishedSection.appendChild(unfinishedHeading);
    unfinishedSection.appendChild(unfinishedList);
    unfinishedSection.appendChild(unfinishedHint);

    const overdueSection = make('section', 'workbench-overdue-section');
    const overdueHeading = make('h3', null, '逾期任务');
    const overdueList = make('ul', 'workbench-overdue-list');
    const overdueHint = make('p', null, '暂无逾期任务');
    overdueHint.setAttribute('class', 'workbench-empty-hint');
    overdueSection.appendChild(overdueHeading);
    overdueSection.appendChild(overdueList);
    overdueSection.appendChild(overdueHint);

    root.appendChild(summary);
    root.appendChild(unfinishedSection);
    root.appendChild(overdueSection);

    nodes = {
      root,
      unfinishedCount,
      overdueCount,
      countNodes,
      unfinishedList,
      unfinishedHint,
      overdueList,
      overdueHint,
    };
    return nodes;
  }

  // 条目自带 data-task-id / data-task-title，点击经 navigate 进入该任务详情。
  function buildItem(record, testid) {
    const item = make('li', testid);
    item.setAttribute('class', 'workbench-task-item');
    item.setAttribute('data-task-id', record.id);
    item.setAttribute('data-task-title', record.title);
    item.appendChild(make('span', null, record.title));
    const dueDate = readDueDate(record);
    if (dueDate !== '') item.appendChild(make('span', null, '截止 ' + dueDate));
    item.addEventListener('click', () => {
      navigate({ view: 'task-detail', params: { taskId: record.id } });
    });
    return item;
  }

  // 每次渲染都向 workbench 重新取数：工作台始终按任务当前数据重算。
  function render() {
    if (!nodes) return null;
    const summary = workbench.getSummary(normalizeToday(today));
    nodes.unfinishedCount.textContent = String(summary.unfinished.length);
    nodes.overdueCount.textContent = String(summary.overdue.length);
    for (const [status] of WORKBENCH_STATUS_LABELS) {
      nodes.countNodes[status].textContent = String(summary.counts[status] || 0);
    }
    fillContainer(
      nodes.unfinishedList,
      summary.unfinished.map((record) => buildItem(record, 'workbench-unfinished-item')),
    );
    fillContainer(
      nodes.overdueList,
      summary.overdue.map((record) => buildItem(record, 'workbench-overdue-item')),
    );
    nodes.unfinishedHint.hidden = summary.unfinished.length > 0;
    nodes.overdueHint.hidden = summary.overdue.length > 0;
    return summary;
  }

  const view = {
    mount(container, params = {}) {
      void params;
      if (!container) throw new Error('workbenchView.mount requires a container');
      host = container;
      doc = container.ownerDocument || (typeof document !== 'undefined' ? document : null);
      if (!doc || typeof doc.createElement !== 'function') {
        throw new Error('workbenchView.mount requires a DOM container');
      }
      build();
      fillContainer(container, [nodes.root]);
      render();
      return view;
    },
    update(params = {}) {
      void params;
      render();
      return view;
    },
    render() {
      render();
      return view;
    },
    unmount() {
      host = null;
      nodes = null;
      return undefined;
    },
  };
  return view;
}

