// L1 topics 业务域（选题管理：数据能力 T1–T4）+ 选题视图（U3）
// 依赖：数据能力只接收注入的 store 与 L0 基础设施；视图只接收注入端口
// （topics / materials 只读 / flows / navigate / today / chrome），
// 自身不读写 localStorage，也不修改 location / history。
import { newId, toLocalISODate } from '../infra/storage.js';

export const TOPIC_ERROR_CODES = ['TITLE_REQUIRED', 'PRIORITY_INVALID', 'TOPIC_NOT_FOUND', 'STORAGE_ERROR'];
export const TOPIC_PRIORITIES = ['high', 'medium', 'low'];

export const TOPIC_ERROR_MESSAGES = {
  TITLE_REQUIRED: '标题不能为空，选题未保存',
  PRIORITY_INVALID: '优先级无效，请选择高／中／低',
  TOPIC_NOT_FOUND: '选题不存在，可能已被删除',
  TOPIC_HAS_TASK: '该选题已创建内容任务，不能删除',
  STORAGE_ERROR: '保存失败，存储不可写，请重试',
};

// 「创建内容任务」失败时的提示（错误码来自 flows.createTaskFromTopic / tasks）。
const CREATE_TASK_ERROR_MESSAGES = {
  TOPIC_NOT_FOUND: '选题不存在，可能已被删除',
  TITLE_REQUIRED: '选题标题为空，无法创建内容任务',
  STORAGE_ERROR: '保存失败，存储不可写，请重试',
};

const PRIORITY_LABELS = [['high', '高'], ['medium', '中'], ['low', '低']];

function normalizeText(value) {
  return typeof value === 'string' ? value : '';
}

// 标题 trim 后为空视为缺失；有效时返回 trim 后的标题。
function readTitle(title) {
  const trimmed = typeof title === 'string' ? title.trim() : '';
  return trimmed === '' ? null : trimmed;
}

export function createTopicsModule({ store, priorityDefault = 'medium' } = {}) {
  if (!store) throw new Error('createTopicsModule requires { store }');
  const defaultPriority = TOPIC_PRIORITIES.includes(priorityDefault) ? priorityDefault : 'medium';

  function readRecords() {
    const records = store.readAll();
    return Array.isArray(records) ? records : [];
  }

  function findRecord(id) {
    return readRecords().find((record) => record && record.id === id) || null;
  }

  function linkList(record) {
    return Array.isArray(record && record.materialIds) ? record.materialIds.slice() : [];
  }

  // 缺省／空值使用 priorityDefault；三档之外返回 PRIORITY_INVALID。
  function readPriority(priority) {
    if (priority === undefined || priority === null || priority === '') {
      return { ok: true, priority: defaultPriority };
    }
    if (typeof priority === 'string' && TOPIC_PRIORITIES.includes(priority)) {
      return { ok: true, priority };
    }
    return { ok: false, code: 'PRIORITY_INVALID' };
  }

  // 素材关联只写 materialIds，不触碰其它字段与其它集合。
  function writeMaterialIds(id, materialIds) {
    const written = store.updateById(id, { materialIds, updatedAt: toLocalISODate() });
    if (!written || written.ok !== true) return { ok: false, code: 'STORAGE_ERROR' };
    return { ok: true, record: written.record };
  }

  return {
    priorityDefault: defaultPriority,
    list() {
      return readRecords();
    },
    get(id) {
      return findRecord(id);
    },
    create({ title, angle, priority } = {}) {
      const trimmedTitle = readTitle(title);
      if (trimmedTitle === null) return { ok: false, code: 'TITLE_REQUIRED' };
      const read = readPriority(priority);
      if (!read.ok) return { ok: false, code: read.code };
      const today = toLocalISODate();
      const record = {
        id: newId('topic'),
        title: trimmedTitle,
        angle: normalizeText(angle),
        priority: read.priority,
        materialIds: [],
        createdAt: today,
        updatedAt: today,
      };
      const written = store.insert(record);
      if (!written || written.ok !== true) return { ok: false, code: 'STORAGE_ERROR' };
      return { ok: true, record };
    },
    // update 只改标题／内容角度／优先级，不修改 materialIds。
    update(id, { title, angle, priority } = {}) {
      const existing = findRecord(id);
      if (!existing) return { ok: false, code: 'TOPIC_NOT_FOUND' };
      const patch = {};
      if (title !== undefined) {
        const trimmedTitle = readTitle(title);
        if (trimmedTitle === null) return { ok: false, code: 'TITLE_REQUIRED' };
        patch.title = trimmedTitle;
      }
      if (angle !== undefined) patch.angle = normalizeText(angle);
      if (priority !== undefined) {
        if (!(typeof priority === 'string' && TOPIC_PRIORITIES.includes(priority))) {
          return { ok: false, code: 'PRIORITY_INVALID' };
        }
        patch.priority = priority;
      }
      patch.updatedAt = toLocalISODate();
      const written = store.updateById(id, patch);
      if (!written || written.ok !== true) return { ok: false, code: 'STORAGE_ERROR' };
      return { ok: true, record: written.record };
    },
    // remove 只删自身记录（materialIds 随记录消失），素材记录保留。
    remove(id) {
      const existing = findRecord(id);
      if (!existing) return { ok: false, code: 'TOPIC_NOT_FOUND' };
      const written = store.removeById(id);
      if (!written || written.ok !== true) return { ok: false, code: 'STORAGE_ERROR' };
      return { ok: true, removed: written.removed === true, record: existing };
    },
    // 幂等：已关联返回 added:false；无效素材 ID 静默忽略，不写入。
    linkMaterial(topicId, materialId) {
      const existing = findRecord(topicId);
      if (!existing) return { ok: false, code: 'TOPIC_NOT_FOUND' };
      const materialIds = linkList(existing);
      if (typeof materialId !== 'string' || materialId === '') {
        return { ok: true, added: false, materialIds };
      }
      if (materialIds.includes(materialId)) return { ok: true, added: false, materialIds };
      const next = materialIds.concat([materialId]);
      const written = writeMaterialIds(topicId, next);
      if (!written.ok) return written;
      return { ok: true, added: true, materialIds: next };
    },
    // 幂等：未关联时也返回 ok:true（removed:false）。
    unlinkMaterial(topicId, materialId) {
      const existing = findRecord(topicId);
      if (!existing) return { ok: false, code: 'TOPIC_NOT_FOUND' };
      const materialIds = linkList(existing);
      if (!materialIds.includes(materialId)) return { ok: true, removed: false, materialIds };
      const next = materialIds.filter((id) => id !== materialId);
      const written = writeMaterialIds(topicId, next);
      if (!written.ok) return written;
      return { ok: true, removed: true, materialIds: next };
    },
    getMaterialIds(topicId) {
      const record = findRecord(topicId);
      return record ? linkList(record) : [];
    },
    // 反查：一个素材可关联多个选题（多对多）。
    listTopicIdsByMaterial(materialId) {
      if (typeof materialId !== 'string' || materialId === '') return [];
      return readRecords()
        .filter((record) => record && linkList(record).includes(materialId))
        .map((record) => record.id);
    },
    // 供 flows.deleteMaterial 清理级联：返回受影响选题 ID，未知素材静默返回空列表。
    removeMaterialLinks(materialId) {
      const affectedTopicIds = [];
      for (const record of readRecords()) {
        const materialIds = linkList(record);
        if (!materialIds.includes(materialId)) continue;
        const written = writeMaterialIds(record.id, materialIds.filter((id) => id !== materialId));
        if (!written.ok) return { ok: false, code: 'STORAGE_ERROR', affectedTopicIds };
        affectedTopicIds.push(record.id);
      }
      return { ok: true, affectedTopicIds };
    },
  };
}

function fillContainer(container, children) {
  if (typeof container.replaceChildren === 'function') {
    container.replaceChildren(...children);
    return;
  }
  while (container.firstChild) container.removeChild(container.firstChild);
  for (const child of children) container.appendChild(child);
}

export function createTopicsView({ topics, materials, flows, navigate, today, chrome } = {}) {
  if (!topics || !materials || !flows || typeof navigate !== 'function') {
    throw new Error('createTopicsView requires { topics, materials, flows, navigate }');
  }
  // 「创建内容任务」入口经 flows.createTaskFromTopic 幂等创建，再由 navigate 端口进入任务详情；
  // 视图不自行改路由、不直接写任务集合。
  void today;

  const defaultPriority = TOPIC_PRIORITIES.includes(topics.priorityDefault) ? topics.priorityDefault : 'medium';
  const state = {
    editingId: null,
    draft: { title: '', angle: '', priority: defaultPriority },
    syncForm: true,
  };
  let host = null;
  let doc = null;
  let nodes = null;

  function currentDoc() {
    if (doc) return doc;
    if (host && host.ownerDocument) return host.ownerDocument;
    if (typeof document !== 'undefined') return document;
    return null;
  }

  function chromeNode(testid) {
    const ownerDoc = currentDoc();
    if (!ownerDoc || typeof ownerDoc.querySelector !== 'function') return null;
    return ownerDoc.querySelector('[data-testid="' + testid + '"]');
  }

  // 校验提示统一写入页面唯一的 error-text 区域（由外壳注入的 chrome 端口或页面定位点）。
  function showError(message) {
    if (chrome && typeof chrome.showError === 'function') {
      chrome.showError(message);
      return;
    }
    const node = chromeNode('error-text');
    if (node) {
      node.textContent = message;
      node.hidden = false;
    }
  }

  function clearError() {
    if (chrome && typeof chrome.clearError === 'function') {
      chrome.clearError();
      return;
    }
    const node = chromeNode('error-text');
    if (node) {
      node.textContent = '';
      node.hidden = true;
    }
  }

  function make(tag, testid, text) {
    const element = doc.createElement(tag);
    if (testid) element.setAttribute('data-testid', testid);
    if (text !== undefined) element.textContent = text;
    return element;
  }

  function addField(form, tag, testid, labelText) {
    const label = make('label', null, labelText);
    label.setAttribute('for', testid);
    const control = make(tag, testid);
    control.setAttribute('id', testid);
    if (tag === 'input') control.setAttribute('type', 'text');
    form.appendChild(label);
    form.appendChild(control);
    return control;
  }

  function build() {
    const root = make('section', 'topics-view');
    root.setAttribute('class', 'topics-view');

    const toolbar = make('div', 'topics-toolbar');
    const newButton = make('button', 'topics-new-button', '新建选题');
    newButton.setAttribute('type', 'button');
    toolbar.appendChild(newButton);

    const form = make('form', 'topics-form');
    form.setAttribute('class', 'topics-form');
    const titleInput = addField(form, 'input', 'topics-title-input', '标题（必填）');
    const angleInput = addField(form, 'input', 'topics-angle-input', '内容角度（可选）');
    const prioritySelect = addField(form, 'select', 'topics-priority-select', '优先级');
    for (const [value, label] of PRIORITY_LABELS) {
      const option = make('option', null, label);
      option.setAttribute('value', value);
      prioritySelect.appendChild(option);
    }

    const pickerSection = make('div', 'topics-material-picker-section');
    const pickerLabel = make('p', 'topics-material-picker-label', '关联素材（勾选后保存即建立关联）');
    const materialList = make('ul', 'topics-material-list');
    pickerSection.appendChild(pickerLabel);
    pickerSection.appendChild(materialList);

    const linkedSection = make('div', 'topics-linked-materials-section');
    const linkedLabel = make('p', 'topics-linked-materials-label', '已关联素材');
    const linkedList = make('ul', 'topics-linked-materials');
    linkedSection.appendChild(linkedLabel);
    linkedSection.appendChild(linkedList);

    const actions = make('div', 'topics-form-actions');
    const saveButton = make('button', 'topics-save-button', '保存');
    saveButton.setAttribute('type', 'button');
    const cancelButton = make('button', 'topics-cancel-button', '取消编辑');
    cancelButton.setAttribute('type', 'button');
    actions.appendChild(saveButton);
    actions.appendChild(cancelButton);

    form.appendChild(pickerSection);
    form.appendChild(linkedSection);
    form.appendChild(actions);

    const listSection = make('section', 'topics-list-section');
    const list = make('ul', 'topics-list');
    const emptyHint = make('p', 'topics-empty-hint', '暂无选题');
    listSection.appendChild(list);
    listSection.appendChild(emptyHint);

    root.appendChild(toolbar);
    root.appendChild(form);
    root.appendChild(listSection);

    nodes = {
      root,
      newButton,
      titleInput,
      angleInput,
      prioritySelect,
      materialList,
      linkedList,
      saveButton,
      cancelButton,
      list,
      emptyHint,
      materialCheckboxes: [],
    };

    newButton.addEventListener('click', () => startNew());
    cancelButton.addEventListener('click', () => startNew());
    saveButton.addEventListener('click', () => save());
    form.addEventListener('submit', (event) => {
      if (event && typeof event.preventDefault === 'function') event.preventDefault();
      save();
    });
    return nodes;
  }

  function buildItem(record) {
    const item = make('li', 'topics-item');
    item.setAttribute('class', 'topics-item');
    item.setAttribute('data-topic-id', record.id);
    item.setAttribute('data-topic-title', record.title);

    const title = make('span', 'topic-title', record.title);
    title.setAttribute('class', 'topic-title');
    item.appendChild(title);

    const priority = make('span', 'topic-priority', record.priority);
    priority.setAttribute('class', 'topic-priority');
    priority.setAttribute('data-topic-priority', record.priority);
    item.appendChild(priority);

    // 尚未添加选题编辑入口。

    // 从该选题创建内容任务：复制选题标题并进入该任务详情（重复点击进入同一个任务）。
    const createTaskButton = make('button', 'topics-create-task-button', '创建内容任务');
    createTaskButton.setAttribute('type', 'button');
    createTaskButton.addEventListener('click', () => { void createTaskFromTopic(record.id); });
    item.appendChild(createTaskButton);

    // 删除入口：能否删除由 flows.deleteTopic 判定；视图自身不弹任何确认。
    const deleteButton = make('button', 'topics-delete-button', '删除');
    deleteButton.setAttribute('type', 'button');
    deleteButton.addEventListener('click', () => { void handleDelete(record.id); });
    item.appendChild(deleteButton);
    return item;
  }

  function renderList() {
    const records = topics.list();
    fillContainer(nodes.list, records.map((record) => buildItem(record)));
    nodes.emptyHint.hidden = records.length > 0;
    return records;
  }

  // 素材勾选项来自素材库只读接口：视图不写素材集合。
  function rebuildMaterialPicker() {
    const records = materials.list();
    const items = records.map((record) => {
      const item = make('li', 'topics-material-item');
      item.setAttribute('data-material-id', record.id);
      const label = make('label', null);
      const box = make('input', 'topics-material-checkbox');
      box.setAttribute('type', 'checkbox');
      box.setAttribute('data-material-id', record.id);
      const caption = make('span', 'topics-material-title', record.title);
      label.appendChild(box);
      label.appendChild(caption);
      item.appendChild(label);
      return { item, box };
    });
    nodes.materialCheckboxes = items.map((entry) => entry.box);
    fillContainer(nodes.materialList, items.map((entry) => entry.item));
    return nodes.materialCheckboxes;
  }

  function renderLinkedMaterials() {
    const topicId = state.editingId;
    const linkedIds = topicId ? topics.getMaterialIds(topicId) : [];
    const entries = linkedIds.map((materialId) => {
      const record = materials.get(materialId);
      const item = make('li', 'topics-linked-material');
      item.setAttribute('data-material-id', materialId);
      item.textContent = record ? record.title : materialId;
      return item;
    });
    fillContainer(nodes.linkedList, entries);
    return entries;
  }

  function syncForm() {
    if (!state.syncForm) return;
    if (nodes.titleInput.value !== state.draft.title) nodes.titleInput.value = state.draft.title;
    if (nodes.angleInput.value !== state.draft.angle) nodes.angleInput.value = state.draft.angle;
    if (nodes.prioritySelect.value !== state.draft.priority) nodes.prioritySelect.value = state.draft.priority;
    const linkedIds = state.editingId ? topics.getMaterialIds(state.editingId) : [];
    for (const box of nodes.materialCheckboxes) {
      const materialId = box.getAttribute('data-material-id');
      box.checked = linkedIds.includes(materialId);
    }
    state.syncForm = false;
  }

  function render() {
    if (!nodes) return;
    rebuildMaterialPicker();
    syncForm();
    renderLinkedMaterials();
    renderList();
  }

  function startNew() {
    state.editingId = null;
    state.draft = { title: '', angle: '', priority: defaultPriority };
    state.syncForm = true;
    clearError();
    render();
  }

  function startEdit(id) {
    const record = topics.get(id);
    if (!record) {
      showError(TOPIC_ERROR_MESSAGES.TOPIC_NOT_FOUND);
      return;
    }
    state.editingId = record.id;
    state.draft = {
      title: record.title,
      angle: normalizeText(record.angle),
      priority: TOPIC_PRIORITIES.includes(record.priority) ? record.priority : defaultPriority,
    };
    state.syncForm = true;
    clearError();
    render();
  }

  function readSelectedMaterialIds() {
    return nodes.materialCheckboxes
      .filter((box) => box.checked === true)
      .map((box) => box.getAttribute('data-material-id'));
  }

  // 勾选状态在保存时统一提交：关联与解除关联都只经 topics 的素材关联接口。
  function syncMaterialLinks(topicId, selectedIds) {
    const currentIds = topics.getMaterialIds(topicId);
    for (const materialId of selectedIds) {
      if (!currentIds.includes(materialId)) topics.linkMaterial(topicId, materialId);
    }
    for (const materialId of currentIds) {
      if (!selectedIds.includes(materialId)) topics.unlinkMaterial(topicId, materialId);
    }
  }

  function save() {
    const values = {
      title: nodes.titleInput.value,
      angle: nodes.angleInput.value,
      priority: nodes.prioritySelect.value,
    };
    const result = state.editingId
      ? topics.update(state.editingId, values)
      : topics.create(values);
    if (!result || result.ok !== true) {
      // 失败时保留已填内容：不回写表单、不改列表。
      showError(
        (result && TOPIC_ERROR_MESSAGES[result.code]) || TOPIC_ERROR_MESSAGES.STORAGE_ERROR,
      );
      return result || { ok: false, code: 'STORAGE_ERROR' };
    }
    syncMaterialLinks(result.record.id, readSelectedMaterialIds());
    const saved = topics.get(result.record.id) || result.record;
    state.editingId = saved.id;
    state.draft = {
      title: saved.title,
      angle: normalizeText(saved.angle),
      priority: saved.priority,
    };
    state.syncForm = true;
    clearError();
    render();
    return result;
  }

  // 「创建内容任务」：幂等（已存在则进入同一个任务），成功后经 navigate 进入任务详情。
  async function createTaskFromTopic(topicId) {
    const result = await flows.createTaskFromTopic({ topicId });
    if (!result || result.ok !== true) {
      showError(
        (result && CREATE_TASK_ERROR_MESSAGES[result.code]) || CREATE_TASK_ERROR_MESSAGES.STORAGE_ERROR,
      );
      return result || { ok: false, code: 'STORAGE_ERROR' };
    }
    clearError();
    const target = result.navigateTo || { view: 'task-detail', taskId: result.task.id };
    const params = target.params && typeof target.params === 'object'
      ? target.params
      : { taskId: target.taskId };
    navigate({ view: target.view || 'task-detail', params });
    return result;
  }

  async function handleDelete(topicId) {
    const result = await flows.deleteTopic({ topicId });
    if (!result || result.ok !== true) {
      showError((result && TOPIC_ERROR_MESSAGES[result.code]) || TOPIC_ERROR_MESSAGES.STORAGE_ERROR);
      return result || { ok: false, code: 'STORAGE_ERROR' };
    }
    if (state.editingId === topicId) {
      state.editingId = null;
      state.draft = { title: '', angle: '', priority: defaultPriority };
      state.syncForm = true;
    }
    clearError();
    render();
    return result;
  }

  const view = {
    mount(container, params = {}) {
      if (!container) throw new Error('topicsView.mount requires a container');
      host = container;
      doc = container.ownerDocument || (typeof document !== 'undefined' ? document : null);
      if (!doc || typeof doc.createElement !== 'function') {
        throw new Error('topicsView.mount requires a DOM container');
      }
      state.editingId = null;
      state.draft = { title: '', angle: '', priority: defaultPriority };
      state.syncForm = true;
      build();
      fillContainer(container, [nodes.root]);
      clearError();
      const topicId = params && typeof params.topicId === 'string' ? params.topicId : '';
      if (topicId !== '') startEdit(topicId);
      else render();
      return view;
    },
    update(params = {}) {
      const topicId = params && typeof params.topicId === 'string' ? params.topicId : '';
      if (topicId !== '') startEdit(topicId);
      else startNew();
      return view;
    },
    render() {
      render();
      return view;
    },
    unmount() {
      host = null;
      nodes = null;
      state.editingId = null;
      return undefined;
    },
  };
  return view;
}

